 updateFighter(player,d,true);updateAI(d);updateFighter(enemy,d,false);resolveCombat();
 for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.x+=p.vx*d;p.life-=d;const target=p.owner==='hero'?enemy:player;if(!p.hit&&Math.abs(p.x-target.x)<27&&Math.abs(p.y-(target.y-34))<38){p.hit=true;applyHit(target,p.owner==='hero'?player:enemy,9,5.2,2.4);burst(p.x,p.y,'#9bffe0',11)}if(p.life<=0||p.hit||p.x<-30||p.x>990)projectiles.splice(i,1)}
